/**
 * Offline license validation using HMAC-SHA-256.
 * Codes are generated by the seller and validated locally without internet.
 *
 * Format: BAROPT-{storeId:4}-{hmac[0:4]}-{hmac[4:8]}
 * Example: BAROPT-0023-A3KP-X7MQ
 */

const SECRET = import.meta.env.VITE_LICENSE_SECRET as string ?? 'BarOpt@2026#Kx9m-Pq3rVn8w-Zj5tYd'
const STORAGE_KEY = 'baropt-license'

// ── HMAC helpers ──────────────────────────────────────────────────────────────

async function hmacHex(message: string): Promise<string> {
  const enc = new TextEncoder()
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(SECRET),
    { name: 'HMAC', hash: 'SHA-256' },
    false, ['sign']
  )
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(message))
  return Array.from(new Uint8Array(sig))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
    .toUpperCase()
}

// ── Code generation (used in the generator tool) ──────────────────────────────

export async function generateLicenseCode(storeId: number): Promise<string> {
  const id = String(storeId).padStart(4, '0')
  const hex = await hmacHex(id)
  const part1 = hex.slice(0, 4)
  const part2 = hex.slice(4, 8)
  return `BAROPT-${id}-${part1}-${part2}`
}

// ── Code validation ───────────────────────────────────────────────────────────

export async function validateLicenseCode(input: string): Promise<boolean> {
  const code = input.trim().toUpperCase().replace(/[\s_]/g, '-')
  const parts = code.split('-')
  if (parts.length !== 4) return false
  if (parts[0] !== 'BAROPT') return false
  if (!/^\d{4}$/.test(parts[1])) return false

  const storeId = parts[1]
  const entered = parts[2] + parts[3]

  const hex = await hmacHex(storeId)
  const expected = hex.slice(0, 8)

  return entered === expected
}

// ── Persistence ───────────────────────────────────────────────────────────────

export function isActivated(): boolean {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return false
    const data = JSON.parse(raw) as { code: string; activatedAt: string }
    return !!data.code
  } catch {
    return false
  }
}

export function saveActivation(code: string): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      code,
      activatedAt: new Date().toISOString(),
    }))
  } catch { /* ignore */ }
}

export function getLicenseInfo(): { code: string; storeId: string; activatedAt: string } | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const data = JSON.parse(raw) as { code: string; activatedAt: string }
    const parts = data.code.split('-')
    return { code: data.code, storeId: parts[1] ?? '0000', activatedAt: data.activatedAt }
  } catch {
    return null
  }
}
